IDP_SUPPORTS = {"saml", "oidc"}

APPS = [
    {"name": "legacy-hr", "protocols": ["saml"]},
    {"name": "api-portal", "protocols": ["oidc"]},
    {"name": "old-erp", "protocols": ["ldap"]},
    {"name": "data-studio", "protocols": ["saml", "oidc"]},
]

def can_federate(app):
    return any(p in IDP_SUPPORTS for p in app["protocols"])

def preferred_protocol(app):
    return "oidc" if "oidc" in app["protocols"] else "saml"

federated = 0
for app in APPS:
    if can_federate(app):
        federated += 1
        print(f"{app['name']}: FEDERATED via {preferred_protocol(app)}")
    else:
        print(f"{app['name']}: NOT_FEDERATED")
print(f"Coverage: {federated}/{len(APPS)}")
